// Fence token による遅着 ACK の抑止
export async function ackJob(db: DB, jobId: string, leaseToken: string) {
  const res = await db.query(
    `UPDATE jobs SET status = 'acked' WHERE id = $1 AND status = 'leased' AND lease_token = $2`,
    [jobId, leaseToken]
  );
  if (res.rowCount === 0) throw new ConflictError('stale lease token');
}
